"""matplotlib.testing — testing utilities.

Mirrors upstream's surface so test code that imports from
``matplotlib.testing`` works. Each helper does the same job upstream
does — pin rcParams to deterministic values, configure CI helpers,
etc. — but skips the parts that depend on a Tkinter event loop or
the Agg-rasterised image-comparison harness, which we don't have.
"""


def set_font_settings_for_testing():
    """Force a deterministic font + size + dpi combination so tests
    that render text produce stable output regardless of the host
    machine's font catalogue. Mirrors upstream's helper."""
    try:
        from matplotlib import rcParams
        rcParams['font.family'] = 'sans-serif'
        rcParams['font.sans-serif'] = ['DejaVu Sans']
        rcParams['font.size'] = 10.0
        rcParams['axes.titlesize'] = 'medium'
        rcParams['savefig.dpi'] = 100
    except Exception:
        pass


def set_reproducibility_for_testing():
    """Pin every rc-param that influences rendering reproducibility so
    repeated runs produce byte-identical output."""
    try:
        from matplotlib import rcParams
        rcParams['svg.hashsalt'] = '0'      # deterministic <g id="...">
        rcParams['svg.fonttype'] = 'path'   # text → outlines
        rcParams['pdf.use14corefonts'] = True
        rcParams['ps.useafm'] = True
        rcParams['axes.unicode_minus'] = False
    except Exception:
        pass


def setup():
    """Run both reproducibility + font setup in one call."""
    set_font_settings_for_testing()
    set_reproducibility_for_testing()


# ─── Added: missing helpers from upstream matplotlib.testing ────────


import os, subprocess, sys


def is_ci_environment():
    """True when running in a typical CI provider (GitHub Actions,
    Travis, CircleCI, Azure)."""
    return any(os.environ.get(v) for v in
               ('CI', 'GITHUB_ACTIONS', 'TRAVIS', 'CIRCLECI', 'TF_BUILD'))


def ipython_in_subprocess(requested_backend_name=None):
    """Spawn IPython in a subprocess for a test. The shim doesn't run
    IPython integration tests, so this is a no-op stub that returns
    a tuple matching upstream's signature."""
    return None, None


def subprocess_run_helper(func, *args, timeout=60, extra_env=None):
    """Run ``func`` (passed as a name to a helper module) in a subprocess.
    Used by upstream's parallel-safe test fixtures. The shim just calls
    the function inline since we have no test harness."""
    if callable(func):
        return func(*args)
    return None


def subprocess_run_for_testing(command, *, env=None, timeout=60,
                                stdout=None, stderr=None, check=False,
                                text=True, capture_output=False):
    """Wrap ``subprocess.run`` with a sensible default config for tests."""
    return subprocess.run(command,
                          env=env, timeout=timeout, stdout=stdout,
                          stderr=stderr, check=check, text=text,
                          capture_output=capture_output)
